        index += m

    operations = []

    for i in range(n - 1):
        for j in range(m - 1):
            if A[i][j] == 1 and A[i][j + 1] == 1 and A[i + 1][j] == 1 and A[i + 1][j + 1] == 1:
                operations.append((i + 1, j + 1))

    B = [[0] * m for _ in range(n)]

    for x, y in operations:
        B[x - 1][y - 1] = 1
        B[x - 1][y] = 1
        B[x][y - 1] = 1
        B[x][y] = 1

    possible = True
    for i in range(n):
        for j in range(m):
            if A[i][j] != B[i][j]:
                possible = False
                break
        if not possible:
            break

    if not possible:
        print(-1)
    else:
        print(len(operations))
